import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"How to token max while you still can.","description":"","frontmatter":{"url":"https://x.com/msg/status/2077109267069575512","title":"How to token max while you still can.","author":"michael s galpert","archived":"2026-07-15T00:00:00.000Z","handle":"@msg","published":"2026-07-14T00:00:00.000Z","stats":"40 likes · 1 retweets · 81 bookmarks · 13204 views","tags":["token-maxxing","multi-cli-orchestration","fable-delegator","herdr","subscription-arbitrage"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-14-@msg-575512.md","filePath":"research/tweets/2026-07-14-@msg-575512.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-07-14-@msg-575512.md"};function s(i,e,h,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="how-to-token-max-while-you-still-can-—-msg" tabindex="-1">How to token max while you still can. — @msg <a class="header-anchor" href="#how-to-token-max-while-you-still-can-—-msg" aria-label="Permalink to &quot;How to token max while you still can. — @msg&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/msg/status/2077109267069575512" target="_blank" rel="noreferrer">https://x.com/msg/status/2077109267069575512</a><strong>作者</strong>：michael s galpert（@msg） <strong>發布日期</strong>：2026-07-14 <strong>收錄日期</strong>：2026-07-15 <strong>類型</strong>：Twitter Article <strong>統計</strong>：40 likes · 1 retweets · 81 bookmarks · 13204 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>tl;dr what i set up to be smarter about subsidized tokens.</p><p>I came across this post from @coreyhainesco and it definitely was a scroll stopper. I was impressed hee was squeezing $8k out of his $200 plan and felt fomo because I knew he was right reminding me that this won&#39;t last long. I remember when it used to cost $5 to get anywhere in SF when Uber and Lyft first were around and now it costs 3-6x that depending on traffic. We will probably see the same thing play out in 12-18 months with frontier models. So if two of the best capitalized companies in history are competing to sell me a dollar for two cents I best be token maxxing before they go public and need to please the markets. Anyone know the German word for fomo - token maxxing edition 😃 Rather than stressing, I wanted to do something about the feeling that I was just throwing away the opportunity to be building more software for relatively free while I still could.</p><h2 id="measure-before-you-maxx" tabindex="-1">Measure before you Maxx <a class="header-anchor" href="#measure-before-you-maxx" aria-label="Permalink to &quot;Measure before you Maxx&quot;">​</a></h2><p>Before getting started, I wanted to take stock of what tokens I have access to because, as our elders used to say, you cannot max what you cannot measure. I installed @steipete&#39;s CodexBar. It&#39;s a macOS menu bar app that keeps every provider&#39;s usage limits visible and shows when it resets. I then made sure that I had all the latest CLIs installed on my machine. I already had Claude ($200), Codex ($200), Cursor ($20) and Droid ($20). I was missing Grok Build (via X premium) and Antigravity (~$150). Now that I know what I&#39;m working with, I need to make sure my agents do too. These tokens aren&#39;t going to drain themselves.</p><h2 id="fable-the-delegator" tabindex="-1">Fable The Delegator <a class="header-anchor" href="#fable-the-delegator" aria-label="Permalink to &quot;Fable The Delegator&quot;">​</a></h2><p>Since Fable came out, the meta has been to use it as a delegator and have Codex be the workhorse, but there are tasks that the new Grok 4.5 can do, or that Composer 2.5 could be better for the task. Evals and routing require more research, but in the meanwhile we are just setting up the round robin for the various harnesses. So Claude and I stood up fable-delegator. It allows me to plan with Claude and then implement via Codex, Grok, Cursor, Antigravity, or Droid CLIs depending on their own token pools. You can see the claude.md file here. Fable plans and delegates and currently verifies the work (going to probably adjust verification with a separate agent in the future). The implementation itself gets farmed to whichever CLI has quota. For large projects it runs a check via the CodexBar CLI. If one rate limits, a model-overlap map fails over to another CLI carrying the same model family. CodexBar tells me which pool has room. fable-delegator has instruction skills for how to use any CLI and what responses to expect. You can see the ones I&#39;ve set up here.</p><p>You can also see or adjust the failover flows because which is helpful since cursor, droid and agy have other models besides their own. You can see that here. Of note: certain tasks don&#39;t need to spin up a separate harness, so be sure to set up CLIProxyAPI. It&#39;s a local server that re-exposes the same CLI subscription logins as plain OpenAI/Anthropic-compatible HTTP endpoints, with no harness. For bulk raw generation ex: draft/rewrite/summarize/classify/extract at volume, LLM-as-judge, fan-out. Another way to token maxx is to set up an agent multiplexer.</p><h2 id="herdr-dev-one-terminal-for-all-the-agent-clis" tabindex="-1">Herdr.dev: one terminal for all the agent CLIs <a class="header-anchor" href="#herdr-dev-one-terminal-for-all-the-agent-clis" aria-label="Permalink to &quot;Herdr.dev: one terminal for all the agent CLIs&quot;">​</a></h2><h2 id="my-friend-runsonai-told-me-to-look-at-herdrdev-to-help-orchestrate-the-various-agents-and-subagents-herdr-is-a-terminal-multiplexer-built-for-coding-agents-you-have-panes-and-tabs-and-sessions-persist-after-you-are-done-you-are-also-able-to-view-an-agent-status-glance-that-shows-which-agent-is-blocked-working-done-or-idle-the-best-part-of-herdr-is-you-can-have-your-agent-orchestrate-the-various-subagent-panes-through-a-json-socket-api-so-an-agent-can-drive-the-whole-workspace-not-just-sit-in-one-pane-you-can-also-have-several-projects-in-one-place-you-watch-the-work-being-done-or-you-let-an-agent-watch-it-for-you-and-check-in-from-your-phone-i-watched-two-herdr-video-walkthroughs-at-2x-to-know-what-to-expect-the-first-and-the-second-it-was-easy-enough-to-set-up-but-i-still-need-to-put-it-through-the-ringer-one-neat-bonus-thing-i-discovered-using-herdr-was-that-when-codex-clis-are-spun-up-you-can-view-them-in-the-chatgpt-iphone-app-under-the-remote-tab" tabindex="-1">My friend @runsonai told me to look at @herdrdev to help orchestrate the various agents and subagents. Herdr is a terminal multiplexer built for coding agents. You have panes and tabs, and sessions persist after you are done. You are also able to view an agent status glance that shows which agent is blocked, working, done, or idle. The best part of Herdr is you can have your agent orchestrate the various subagent panes through a JSON socket API, so an agent can drive the whole workspace, not just sit in one pane. You can also have several projects in one place. You watch the work being done, or you let an agent watch it for you and check in from your phone. I watched two Herdr video walkthroughs at 2x to know what to expect: the first and the second. It was easy enough to set up but I still need to put it through the ringer. One neat bonus thing I discovered using Herdr was that when Codex CLIs are spun up, you can view them in the ChatGPT iPhone app under the remote tab. <a class="header-anchor" href="#my-friend-runsonai-told-me-to-look-at-herdrdev-to-help-orchestrate-the-various-agents-and-subagents-herdr-is-a-terminal-multiplexer-built-for-coding-agents-you-have-panes-and-tabs-and-sessions-persist-after-you-are-done-you-are-also-able-to-view-an-agent-status-glance-that-shows-which-agent-is-blocked-working-done-or-idle-the-best-part-of-herdr-is-you-can-have-your-agent-orchestrate-the-various-subagent-panes-through-a-json-socket-api-so-an-agent-can-drive-the-whole-workspace-not-just-sit-in-one-pane-you-can-also-have-several-projects-in-one-place-you-watch-the-work-being-done-or-you-let-an-agent-watch-it-for-you-and-check-in-from-your-phone-i-watched-two-herdr-video-walkthroughs-at-2x-to-know-what-to-expect-the-first-and-the-second-it-was-easy-enough-to-set-up-but-i-still-need-to-put-it-through-the-ringer-one-neat-bonus-thing-i-discovered-using-herdr-was-that-when-codex-clis-are-spun-up-you-can-view-them-in-the-chatgpt-iphone-app-under-the-remote-tab" aria-label="Permalink to &quot;My friend @runsonai told me to look at @herdrdev to help orchestrate the various agents and subagents.
Herdr is a terminal multiplexer built for coding agents. You have panes and tabs, and sessions persist after you are done. You are also able to view an agent status glance that shows which agent is blocked, working, done, or idle.
The best part of Herdr is you can have your agent orchestrate the various subagent panes through a JSON socket API, so an agent can drive the whole workspace, not just sit in one pane. You can also have several projects in one place. You watch the work being done, or you let an agent watch it for you and check in from your phone.
I watched two Herdr video walkthroughs at 2x to know what to expect: the first and the second. It was easy enough to set up but I still need to put it through the ringer.
One neat bonus thing I discovered using Herdr was that when Codex CLIs are spun up, you can view them in the ChatGPT iPhone app under the remote tab.&quot;">​</a></h2><h2 id="what-am-i-missing" tabindex="-1">What am I missing? <a class="header-anchor" href="#what-am-i-missing" aria-label="Permalink to &quot;What am I missing?&quot;">​</a></h2><h2 id="what-do-you-use-squeeze-the-most-out-of-your-subscriptions" tabindex="-1">What do you use squeeze the most out of your subscriptions? <a class="header-anchor" href="#what-do-you-use-squeeze-the-most-out-of-your-subscriptions" aria-label="Permalink to &quot;What do you use squeeze the most out of your subscriptions?&quot;">​</a></h2><h2 id="stay-tuned" tabindex="-1">Stay Tuned <a class="header-anchor" href="#stay-tuned" aria-label="Permalink to &quot;Stay Tuned&quot;">​</a></h2><p>I will share more of the things I&#39;m spending my tokens on and will report back in 30 days with how much I was able to arb. So follow @msg</p><h2 id="in-the-meanwhile-may-your-token-maxxing-bring-joy-and-prosperity-to-the-world" tabindex="-1">In the meanwhile, may your token maxxing bring joy and prosperity to the world. <a class="header-anchor" href="#in-the-meanwhile-may-your-token-maxxing-bring-joy-and-prosperity-to-the-world" aria-label="Permalink to &quot;In the meanwhile, may your token maxxing bring joy and prosperity to the world.&quot;">​</a></h2><hr><p>Also while I was writing this, I saw that @cjzafir setup a codex plugin to do similar orchestration. CJ Zafir&#39;s Codex-Orchestration</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：作者搭建跨 CLI 訂閱套餐的「token maxxing」系統：CodexBar 監控用量、fable-delegator 讓 Fable 規劃+委派+驗證、Codex/Grok/Cursor/Droid/Antigravity 依配額輪替執行，Herdr 統一 terminal 管理多 agent。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>動機是套利假設：frontier labs 目前補貼 token 價格，類比 Uber/Lyft 早期低價後漲價 3-6 倍，作者預期 12-18 個月內同樣現象會發生在模型定價上，故趁早最大化利用多個訂閱（Claude $200/Codex $200/Cursor $20/Droid $20/Grok Build/Antigravity ~$150）。</li><li>「先測量再最大化」：用 @steipete 的 CodexBar（macOS menu bar app）監看各供應商用量上限與重置時間，作為決策依據。</li><li>fable-delegator 架構：Fable 負責規劃/委派/驗證（暫時），實作依各 CLI 配額動態分派給 Codex/Grok/Cursor/Antigravity/Droid；配額打滿時透過 model-overlap map failover 到同模型家族的其他 CLI。</li><li>CLIProxyAPI：把既有 CLI 訂閱登入態重曝為 OpenAI/Anthropic 相容 HTTP endpoint，免整套 harness 即可做大量 draft/rewrite/summarize/classify/extract/LLM-as-judge 等批次任務。</li><li>Herdr.dev：coding agent 專用 terminal multiplexer，具 pane/tab 持久化 session、agent 狀態總覽（blocked/working/done/idle），並提供 JSON socket API 讓一個 agent 可跨 pane 驅動整個 workspace。</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>訂閱組合：Claude $200、Codex $200、Cursor $20、Droid $20、Grok Build（經 X premium）、Antigravity ~$150</li><li>工具：CodexBar（@steipete）、fable-delegator（自建）、CLIProxyAPI、Herdr.dev（@herdrdev）</li><li>對照案例：@coreyhainesco 從 $200 方案「榨出」$8k 價值（作者引用但未附證據連結）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>全文為個人實驗紀錄與工具清單連結，缺乏量化結果——作者自陳將於 30 天後回報實際套利成果，目前無法驗證效益；引用的「$8k out of $200」案例亦無數據佐證。</li><li>定價套利假設（&quot;won&#39;t last 12-18 months&quot;）與 Uber/Lyft 類比屬推測性論證，非既有數據支持；若補貼提前結束，整套多 CLI 訂閱疊加（合計超過 $500+/月）成本結構可能立即失效。</li><li>Multi-CLI quota-based failover 概念本身具參考價值（配額為路由訊號），但混用不同模型家族完成同一任務生命週期可能引入一致性/品質風險，文中未討論此 trade-off。</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>5/10</td><td>本 workspace 為單一 Claude Code 環境，跨 CLI 訂閱套利場景不直接適用</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>用配額可用性做委派/failover 訊號是具體可行的實務巧思</td></tr><tr><td>C. 證據品質 (20%)</td><td>3/10</td><td>純個人軼事+待補的 30 天後續報告，無量化效益數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>提及具體工具與架構但多為連結指向，非深入技術拆解</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>「配額驅動的多後端路由」原則可泛化至任何多供應商成本優化場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.15/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：分數未過 6，且核心效益宣稱（套利成果）尚待作者 30 天後續報告驗證，暫僅歸檔備查。</p>`,33)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
